# -*- coding: utf-8 -*-
"""IMT Icons v3 — Apple-grade optical system, 31+6 카테고리.
규칙
  1) 캔버스 24x24, 광학 영역 가로 17.6 / 세로 15.6 (넓고 낮게)
  2) 스트로크 1.6 균일, round cap / round join — 굵기 변조 없음
  3) 코너는 연속곡률(슈퍼타원 n=4)
  4) 장식 금지: 액센트 도트·표정·기울기·그림자·그라디언트 없음
  5) 한 아이콘 2~3 패스
"""
from tokens import PALETTE, CATS, STROKE  # noqa: F401

K = 0.909

def C(cx, cy, r):
    return f"M{cx-r:g} {cy:g}a{r:g} {r:g} 0 1 0 {2*r:g} 0a{r:g} {r:g} 0 1 0 {-2*r:g} 0Z"

def SR(x, y, w, h, r):
    k = K * r
    return (f"M{x+r:g} {y:g}H{x+w-r:g}"
            f"C{x+w-r+k:g} {y:g} {x+w:g} {y+r-k:g} {x+w:g} {y+r:g}"
            f"V{y+h-r:g}"
            f"C{x+w:g} {y+h-r+k:g} {x+w-r+k:g} {y+h:g} {x+w-r:g} {y+h:g}"
            f"H{x+r:g}"
            f"C{x+r-k:g} {y+h:g} {x:g} {y+h-r+k:g} {x:g} {y+h-r:g}"
            f"V{y+r:g}"
            f"C{x:g} {y+r-k:g} {x+r-k:g} {y:g} {x+r:g} {y:g}Z")

def DOT(x, y):
    return f"M{x:g} {y:g}h.01"


def GEAR(cx=12, cy=12, r_out=8.2, r_in=6.2, teeth=8, tw=0.42):
    """치차 링 패스 — 8치 기어."""
    import math
    step = 2*math.pi/teeth
    pts = []
    for i in range(teeth):
        a0 = i*step
        for (r, f) in ((r_in, -0.5+ (1-tw)/2*0), ):
            pass
        a_t0 = a0 - step*tw/2
        a_t1 = a0 + step*tw/2
        a_v0 = a0 + step*tw/2 + step*0.14
        a_v1 = a0 + step - step*tw/2 - step*0.14
        for (r, a) in ((r_out, a_t0), (r_out, a_t1), (r_in, a_v0), (r_in, a_v1)):
            pts.append((cx + r*math.cos(a), cy + r*math.sin(a)))
    d = "M" + "L".join(f"{x:.2f} {y:.2f}" for x, y in pts) + "Z"
    return d

ICONS = {}
def add(name, cat, kw, ops, hue):
    ICONS[name] = {"cat": cat, "kw": kw, "ops": ops, "hue": hue}

